/** void MoveItemSlotInList(struct ItemSlot *itemSlots_, u32 from, u32 to_) */
export function MoveItemSlotInList(itemSlots_: any, from: any, to_: any): any {
  let itemSlots: any = itemSlots_;
      let to: any = to_;

      if (from != to)
      {
          let i, count;
          let firstSlot: any = itemSlots[from];

          if (to > from)
          {
              to--;
              for (i = from, count = to; i < count; i++)
                  itemSlots[i] = itemSlots[i + 1];
          }
          else
          {
              for (i = from, count = to; i > count; i--)
                  itemSlots[i] = itemSlots[i - 1];
          }
          itemSlots[to] = firstSlot;
      }
}

